arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9: empty env vars are now preserved (no longer returned as null).
        // Use a helper to distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool IsSet(string variable)
    {
        // IDictionary.Contains checks the OS environment directly —
        // returns false only when the variable is truly absent.
        return Environment.GetEnvironmentVariables().Contains(variable);
    }
}

